  cursor: pointer;
  transition: var(--transition);
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
}

.detail-actions-top .detail-btn.secondary {
  background: rgba(120, 120, 128, 0.16);
  color: var(--text-primary);
}

.detail-actions-top .detail-btn.secondary:hover {
  background: rgba(120, 120, 128, 0.24);
  transform: scale(1.02);
}

.detail-actions-top .detail-btn.primary {
  background: var(--primary-color);
  color: white;
}

.detail-actions-top .detail-btn.primary:hover {
  background: #0056cc;
  transform: scale(1.02);
}

.setting-item {
  margin-bottom: 16px;
  padding-bottom: 12px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.setting-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.setting-item label {
  display: block;
  font-size: 14px;
  font-weight: 600;
  color: var(--text-primary);
  margin-bottom: 8px;
}

.setting-item select {
  width: 100%;
  padding: 8px 12px;
  border: 1px solid var(--border-color);
  border-radius: 8px;
  background: var(--surface-color);
  font-size: 16px;
  color: var(--text-primary);
}

.setting-item input[type='checkbox'] {
  margin-right: 8px;
  transform: scale(1.2);
}

.setting-item span {
  font-size: 16px;
  color: var(--text-primary);
}

.setting-description {
  margin-top: 6px;
}

.setting-description small {
  font-size: 12px;
  color: var(--text-secondary);
  line-height: 1.4;
  display: block;
  font-style: italic;
}

/* 基础详情项样式 */
.detail-item {
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.detail-item:last-child {
  border-bottom: none;
  margin-bottom: 0;
}

.detail-item label {
  display: block;
  font-size: 13px;
  font-weight: 600;
  color: var(--text-secondary);
  text-transform: uppercase;
  letter-spacing: 0.3px;
  margin-bottom: 4px;
}

.detail-item span,
.detail-item div {
  font-size: 16px;
  color: var(--text-primary);
  line-height: 1.5;
  word-wrap: break-word;
}

/* 短内容项目 - 单行显示 */
.detail-item.inline {
  display: flex;
  align-items: flex-start;
  margin-bottom: 10px;
  padding-bottom: 6px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.15);
}

.detail-item.inline label {
  flex-shrink: 0;
  width: 85px;
  margin-bottom: 0;
  margin-right: 12px;
  font-size: 13px;
}

.detail-item.inline span {
  flex: 1;
  font-size: 15px;
  line-height: 1.4;
}

/* 长内容项目 - 块级显示 */
.detail-item.block {
  margin-bottom: 14px;
  padding-bottom: 10px;
}

.detail-item.block label {
  margin-bottom: 6px;
  font-size: 13px;
}

.detail-item.block div {
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
}

/* 组合显示 - 将多个短项目放在一行 */
.detail-row {
  display: flex;
  gap: 20px;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 0.5px solid rgba(120, 120, 128, 0.2);
}

.detail-row .detail-item {
