  word-break: break-word;
  line-height: 1.4;
}

/* 旧的 detail-actions 和 detail-btn 样式已被 detail-actions-inline 替代 */

/* 确认对话框样式 */
.confirmation-dialog-overlay {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  bottom: 0;
  width: 100%;
  height: 100%;
  min-height: 100vh; /* 确保至少占满视口 */
  background: rgba(0, 0, 0, 0.5);
  backdrop-filter: blur(10px);
  -webkit-backdrop-filter: blur(10px);
  z-index: 2000;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  overflow: auto; /* 允许滚动以防内容过大 */
  padding: 20px 10px; /* 增加内边距确保弹框不会贴边 */
}

.confirmation-dialog-overlay.show {
  opacity: 1;
}

.confirmation-dialog {
  background: var(--surface-color);
  border-radius: 12px;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.3);
  width: 85%;
  max-width: 280px;
  overflow: hidden;
  transform: scale(0.9) translateY(20px);
  transition: all 0.3s cubic-bezier(0.25, 0.46, 0.45, 0.94);
  margin: auto; /* 确保居中 */
  position: relative;
}

.confirmation-dialog-overlay.show .confirmation-dialog {
  transform: scale(1) translateY(0);
}

.dialog-header {
  padding: 14px 16px 10px;
  text-align: center;
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
}

.dialog-title {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  color: var(--text-primary);
}

.dialog-content {
  padding: 12px 16px;
  text-align: center;
  max-height: 120px;
  overflow-y: auto;
}

.dialog-message {
  margin: 0;
  font-size: 14px;
  color: var(--text-primary);
  line-height: 1.4;
}

.dialog-options {
  padding: 10px 16px;
  border-top: 0.5px solid rgba(0, 0, 0, 0.1);
  border-bottom: 0.5px solid rgba(0, 0, 0, 0.1);
}

.checkbox-option {
  display: flex;
  align-items: center;
  gap: 6px;
  cursor: pointer;
  font-size: 13px;
  color: var(--text-primary);
  user-select: none;
}

.checkbox-option input[type='checkbox'] {
  width: 16px;
  height: 16px;
  border-radius: 4px;
  border: 1px solid var(--border-color);
  background: var(--surface-color);
  cursor: pointer;
  position: relative;
  margin: 0;
  appearance: none;
  -webkit-appearance: none;
  flex-shrink: 0;
}

.checkbox-option input[type='checkbox']:checked {
  background: var(--primary-color);
  border-color: var(--primary-color);
}

.checkbox-option input[type='checkbox']:checked::after {
  content: '✓';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  color: white;
  font-size: 11px;
  font-weight: bold;
}

.dialog-actions {
  display: flex;
  gap: 0;
}

.dialog-btn {
  flex: 1;
  padding: 12px;
  border: none;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  transition: var(--transition);
  background: transparent;
}

.dialog-btn:not(:last-child) {
  border-right: 0.5px solid rgba(0, 0, 0, 0.1);
}

.dialog-btn.secondary {
  color: var(--text-primary);
}

.dialog-btn.secondary:hover {
  background: rgba(0, 0, 0, 0.05);
}

.dialog-btn.primary {
  color: var(--primary-color);
  font-weight: 700;
}

.dialog-btn.primary:hover {
  background: rgba(0, 122, 255, 0.1);
}

.dialog-btn:active {
  transform: scale(0.98);
}

/* 小屏幕下的对话框优化 */
