/**
 * 剧情小助手 - 主要逻辑控制
 * Story Assistant - Main Logic Controller
 */

$(document).ready(function () {
  // 环境配置
  let isDev = false; // 开发环境标识，打包时会自动改为 false

  // 初始化剧情数据
  let stories = [];
  let currentStoryIndex = 0;
  let currentPlot = '0'; // 来自数据源的currentPlot (现在是uniqueID)
  let currentStepId = '1'; // 来自数据源的当前步骤ID
  let sortOrder = 'asc'; // 排序顺序：'asc' 或 'desc'

  // 主题设置
  let themeSettings = {
    currentTheme: 'default', // 当前主题: default, cute, dark
  };

  // 执行剧情策略设置
  let executionStrategy = {
    mode: 'direct', // 'direct' - 直接执行, 'copy' - 复制到酒馆对话框
  };

  /**
   * 初始化插件
   */
  async function initStoryAssistant() {
    loadThemeSettings(); // 加载主题设置
    loadExecutionStrategySettings(); // 加载执行策略设置
    bindEvents();
    await loadStoryData(); // 异步加载数据，数据加载完成后会自动调用updateDisplay()
  }

  /**
   * 加载主题设置
   */
  function loadThemeSettings() {
    try {
      const saved = localStorage.getItem('storyAssistant_themeSettings');
      if (saved) {
        const settings = JSON.parse(saved);
        themeSettings = { ...themeSettings, ...settings };
      }

      // 应用保存的主题
      applyTheme(themeSettings.currentTheme);
    } catch (error) {
      console.warn('加载主题设置失败:', error);
      // 使用默认主题
      applyTheme('default');
    }
  }

  /**
   * 保存主题设置
   */
  function saveThemeSettings() {
    try {
      localStorage.setItem('storyAssistant_themeSettings', JSON.stringify(themeSettings));
    } catch (error) {
      console.warn('保存主题设置失败:', error);
    }
  }

  /**
   * 加载执行策略设置
   */
  function loadExecutionStrategySettings() {
    try {
      const saved = localStorage.getItem('storyAssistant_executionStrategy');
      if (saved) {
        const settings = JSON.parse(saved);
        executionStrategy = { ...executionStrategy, ...settings };
      }

      console.log('✅ 执行策略设置已加载:', executionStrategy.mode);
    } catch (error) {
      console.warn('加载执行策略设置失败:', error);
      // 使用默认策略
      executionStrategy.mode = 'direct';
    }
  }

  /**
   * 保存执行策略设置
   */
  function saveExecutionStrategySettings() {
    try {
      localStorage.setItem('storyAssistant_executionStrategy', JSON.stringify(executionStrategy));
      console.log('💾 执行策略设置已保存:', executionStrategy.mode);
    } catch (error) {
      console.warn('保存执行策略设置失败:', error);
    }
  }

  /**
   * 应用主题
   */
  function applyTheme(themeName) {
    const body = document.body;

    // 移除之前的主题类
    body.removeAttribute('data-theme');

    // 应用新主题
    if (themeName !== 'default') {
      body.setAttribute('data-theme', themeName);
    }

    // 更新设置
    themeSettings.currentTheme = themeName;

    console.log('✨ 主题已切换至:', themeName);

    // 触发主题变化动画
    const container = document.querySelector('.story-assistant-container');
    if (container) {
      container.style.transform = 'scale(0.98)';
      setTimeout(() => {
        container.style.transform = '';
      }, 200);
    }
  }

  /**
   * 加载剧情数据
   */
  async function loadStoryData() {
    if (isDev) {
      // 开发环境：从 new-plot-data.json 文件读取数据
      console.log('🔧 开发环境：从 new-plot-data.json 加载剧情数据');
      $.getJSON('data/new-plot-data.json')
        .done(function (data) {
          console.log('✅ 开发环境：成功加载外部数据文件');
          console.log('📊 开发环境：currentPlot =', data.currentPlot);
          processPlotData(data);
        })
        .fail(function (jqxhr, textStatus, error) {
          console.error('❌ 开发环境：加载剧情数据失败:', textStatus, error);
          // 回退到默认数据
          loadDefaultData();
        });
    } else {
      // 生产环境：处理剧情数据
      console.log('🚀 生产环境：处理剧情数据');

      // 调用生产环境处理函数
      await processPlotDataForProduction();
    }
  }

  /**
   * 处理剧情数据（开发环境）
   */
  function processPlotData(data) {
    // 处理新格式的数据结构
    const plotList = data.plotList || [];

    // 转换为标准格式 - 每个剧情包含其所有步骤
    stories = plotList.map((plot, index) => {
      // 找到当前执行的步骤
      const currentStep = plot.steps?.find(step => step.isExecute) || plot.steps?.[0] || {};

      return {
        id: plot.uniqueID,
        globalID: plot.globalID,
        title: plot.title,
        content: currentStep.event || '', // 当前步骤的事件作为内容
        description: plot.coreConflict || '',
        location: plot.location || '',
        participants: currentStep.characters ? currentStep.characters.split(',') : [],
        development: currentStep.development || '',
        steps: plot.steps || [],
        currentStepId: currentStep.stepId || '1',
        isExecuted: plot.steps?.some(step => step.isExecute) || false,
      };
    });

    // 按uniqueID排序
    stories.sort((a, b) => parseInt(a.id) - parseInt(b.id));

    // 设置currentPlot（来自数据源）
    const currentPlotData = data.currentPlot || {};
    currentPlot = currentPlotData.uniqueID || '0';
    currentStepId = currentPlotData.stepId || '1';

    console.log('📊 数据源currentPlot设置为：', currentPlot, 'stepId:', currentStepId);

    // 根据currentPlot设置当前剧情索引
    if (currentPlot !== '0') {
      const foundIndex = stories.findIndex(story => story.id === currentPlot);
      if (foundIndex !== -1) {
        currentStoryIndex = foundIndex;
        // 同步当前剧情的currentStepId
        const currentStory = stories[currentStoryIndex];
        if (currentStory) {
          currentStory.currentStepId = currentStepId;
        }
        console.log(`✅ 找到数据源currentPlot ${currentPlot}，对应索引 ${foundIndex}，同步stepId: ${currentStepId}`);
      } else {
        currentStoryIndex = 0;
        console.warn(`⚠️ 数据源currentPlot ${currentPlot} 在剧情列表中未找到，使用索引 0`);
      }
    } else {
      currentStoryIndex = 0;
      console.log('🎭 数据源currentPlot为空，表示未开始任何剧情，即将调用updateDisplay显示未选择状态');
    }

    updateDisplay();
    updateSortButton(); // 初始化排序按钮状态
    console.log('🎬 剧情数据加载完成：');
    console.log('   - 总剧情数：', stories.length);
    console.log('   - 数据源currentPlot：', currentPlot);
    console.log('   - 当前stepId：', currentStepId);
    console.log('   - 初始显示索引：', currentStoryIndex);
    console.log('   - 初始显示剧情：', stories[currentStoryIndex]?.title || '无');
  }

  /**
   * 处理剧情数据（生产环境）
   */
  async function processPlotDataForProduction() {
    console.log('🏭 生产环境：处理剧情数据');

    // 检查是否有内联数据（构建后的版本）
    if (typeof window.plot_data !== 'undefined') {
      console.log('✅ 生产环境：使用内联数据');
      processPlotData(window.plot_data);
      // 成功加载，停止重试机制
      stopRetryMechanism();
      return;
    }

    // 尝试从世界书获取数据
    if (typeof window.initProductionEnvironment === 'function') {
      console.log('🔍 生产环境：尝试从世界书获取剧情数据');

      try {
        const result = await window.initProductionEnvironment();

        if (result.success && result.data) {
          console.log('✅ 生产环境：成功从世界书获取数据');
          processPlotData(result.data);
          // 成功加载，停止重试机制
          stopRetryMechanism();
          showFeedback('✅ 数据加载成功！');
        } else {
          console.error('❌ 生产环境：世界书数据获取失败:', result.error);
          // 只有在首次加载时才显示错误（避免重试时重复显示）
          if (retryCount === 0) {
            showProductionError('世界书数据获取失败', result.error);
          } else {
            // 重试失败，继续下一次重试
            throw new Error(result.error);
          }
        }
      } catch (error) {
        console.error('💥 生产环境：初始化过程出错:', error);
        // 只有在首次加载时才显示错误（避免重试时重复显示）
        if (retryCount === 0) {
          showProductionError('生产环境初始化失败', error.message);
        } else {
          // 重试失败，继续下一次重试
          throw error;
        }
      }
    } else {
      console.warn('⚠️ 生产环境：initProductionEnvironment 函数不可用');
      // 只有在首次加载时才显示错误（避免重试时重复显示）
      if (retryCount === 0) {
        showProductionError('生产环境配置错误', 'initProductionEnvironment 函数不可用，可能未正确加载 init.js');
      } else {
        // 重试失败，继续下一次重试
        throw new Error('initProductionEnvironment 函数不可用');
      }
    }
  }

  /**
   * 显示生产环境错误
   */
  function showProductionError(title, message) {
    console.error('🚨 生产环境错误:', title, '-', message);

    // 显示错误状态
    showNoPlotState(`生产环境错误: ${title}`, `生产环境数据加载失败，请检查世界书配置`);

    // 显示持久错误消息
    const fullErrorMsg = `🚨 生产环境错误\n\n标题: ${title}\n详情: ${message}\n\n请检查：\n1. 是否有名为"剧情元数据-By萧谴剧情模拟器"的世界书条目\n2. 条目内容是否为有效的JSON格式\n3. JSON数据是否包含 currentPlot 和 plotList 字段`;

    showFeedback(fullErrorMsg);

    // 启动重试机制：每隔5秒重试一次，连续重试3次
    startRetryMechanism();
  }

  /**
   * 重试机制：每隔5秒重试一次，连续重试3次
   */
  let retryCount = 0;
  let retryTimer = null;
  const MAX_RETRY_COUNT = 3;
  const RETRY_INTERVAL = 5000; // 5秒

  function startRetryMechanism() {
    // 清除之前的重试定时器（如果存在）
    if (retryTimer) {
      clearTimeout(retryTimer);
    }

    retryCount = 0;
    console.log('🔄 启动重试机制：将每隔5秒重试一次，最多重试3次');

    // 启动第一次重试
    scheduleRetry();
  }

  function scheduleRetry() {
    if (retryCount >= MAX_RETRY_COUNT) {
      console.error('❌ 已达到最大重试次数，停止重试');
      showFeedback(`已重试 ${MAX_RETRY_COUNT} 次，仍无法加载数据。请检查世界书配置。`);
      return;
    }

    retryCount++;
    console.log(`⏰ 准备第 ${retryCount} 次重试，将在 ${RETRY_INTERVAL / 1000} 秒后执行...`);

    showFeedback(`第 ${retryCount} 次重试将在 ${RETRY_INTERVAL / 1000} 秒后开始...`);

    retryTimer = setTimeout(async () => {
      console.log(`🔄 执行第 ${retryCount} 次重试...`);
      showFeedback(`正在执行第 ${retryCount} 次重试...`);

      try {
        // 重新尝试加载数据
        await processPlotDataForProduction();
      } catch (error) {
        console.error(`❌ 第 ${retryCount} 次重试失败:`, error);

        // 如果还有重试次数，继续重试
        if (retryCount < MAX_RETRY_COUNT) {
          scheduleRetry();
        } else {
          console.error('❌ 已达到最大重试次数，停止重试');
          showFeedback(`已重试 ${MAX_RETRY_COUNT} 次，仍无法加载数据。请检查世界书配置。`);
        }
      }
    }, RETRY_INTERVAL);
  }

  /**
   * 停止重试机制
   */
  function stopRetryMechanism() {
    if (retryTimer) {
      clearTimeout(retryTimer);
      retryTimer = null;
    }
    retryCount = 0;
    console.log('⏹️ 重试机制已停止');
  }

