// 定义监听 message_received 事件的函数
async function onMessageReceived(message_id) {
  console.log('收到了新消息！');
  console.log('消息ID:', message_id);

  try {
    // 使用 getChatMessages 获取最后一条消息
    const lastMessages = getChatMessages(-1);

    if (lastMessages && lastMessages.length > 0) {
      const lastMessage = lastMessages[0];
      console.log('获取到最后一条消息:', lastMessage);

      // 检查消息是否已经包含 [剧情推进] 标记，避免重复添加
      if (!lastMessage.message.includes('[剧情推进]')) {
        // 在消息内容后附加 [剧情推进]
        const updatedMessage = lastMessage.message + '\n[剧情推进]';

        // 使用 setChatMessages 更新消息
        await setChatMessages([
          {
            message_id: lastMessage.message_id,
            message: updatedMessage,
          },
        ]);

        console.log('已成功为最后一条消息附加 [剧情推进] 标记');
      } else {
        console.log('消息已包含 [剧情推进] 标记，跳过添加');
      }
    } else {
      console.warn('未能获取到最后一条消息');
    }
  } catch (error) {
    console.error('处理消息时发生错误:', error);
  }
}

// 页面准备就绪后执行监听设置
$(document).ready(function () {
  console.log('页面已准备就绪，开始设置事件监听器');

  // 使用 eventOn 监听 message_received 事件
  // 根据 event.d.ts 中的定义，使用 tavern_events.MESSAGE_RECEIVED
  eventOn(tavern_events.MESSAGE_RECEIVED, onMessageReceived);

  console.log('已设置 message_received 事件监听器');
});

